下面程序中，`a[0]` 与 `b[0]` 的输出分别是什么？（`malloc` 返回的内存内容是脏数据）

```c
int *a = calloc(3, sizeof(int));
int *b = malloc(3 * sizeof(int));
printf("a[0]=%d\n", a[0]);
printf("b 内容是否确定 = %s\n", "否");
```

下面的扩容函数在 `realloc` 失败时会泄漏原内存。指出原因并改正：

```c
int grow(int *p, size_t new_n) {
    p = realloc(p, new_n * sizeof(int));
    if (!p) return -1;
    return 0;
}
```

answer.reference_code:
int grow(int **pp, size_t new_n) {
    if (new_n > SIZE_MAX / sizeof(int)) return -1;
    void *tmp = realloc(*pp, new_n * sizeof(int));
    if (!tmp) return -1;      /* 原 *pp 仍有效，由调用方决定如何处理 */
    *pp = tmp;
    return 0;
}
/* 调用方：
   int *buf = malloc(sizeof(int) * 4);
   if (grow(&buf, 100) != 0) { free(buf); buf = NULL; }
